// Opening story (scenes 1–3) in all game languages. Uncle Saleh's name is localised so every player understands who he is.
export const KEYS_S = ['sn_father', 'sn_saleh', 'sn_me', 's1a', 's1b', 's1c', 's2a', 's2b', 's2c', 's2d', 's2e', 's3a', 's3b', 's3c', 's3d'];
export default {
  ar: ['الأب', 'عم صالح', 'أنت', 'يا ولدي، إذا وصلك هالتسجيل فأنا ما عدت معك. عندي لك أمانة: استوديو «على الهوا». كان أول حلم لي، وسكّرته من عشر سنين.', 'المفتاح مع عم صالح. وخذ الكاميرا الصغيرة والمايك اللي في الصندوق. ما هي شي كثير، بس كل بداية تبدأ صغيرة.', '📌 استلمت: كاميرا صغيرة (مستوى 1) ومايك قديم (مستوى 1).', 'أخيراً جيت! أبوك وصاني أسلّمك المفتاح بيدك. ترى المكان من عشر سنين ما أحد فتحه، استعد للغبار.', 'يلا يا عم صالح، نشوف وش باقي.', 'الباب ينفتح: مكتب قديم، وغرفة اجتماعات، ووسخ في كل مكان.', 'هذا هو الاستوديو؟!', 'كان أحلى استوديو في الحي. والحين صار عليك ترجّعه.', '📌 اضغط على الوسخ عشان تنظفه.', 'ابدأ بالأرض، بعدين المكتب. المكان النظيف يرفع نفسك.', '📌 +10 خبرة.', 'الحين المكان يتنفس. بس الاستوديو بدون محتوى ما يسوى شي. انزل الشارع، كلّم الناس، وصوّر أول مقابلة.'],
  en: ['Dad', 'Uncle Saleh', 'You', 'Son, if this recording reaches you, I am no longer with you. I leave you something precious: the On Air studio. It was my first dream, and I closed it ten years ago.', 'Uncle Saleh has the key. Take the little camera and the microphone in the box. They are not much, but every beginning starts small.', '📌 Received: small camera (level 1) and old microphone (level 1).', 'You finally came! Your father asked me to hand you the key myself. Nobody has opened this place in ten years, so get ready for the dust.', "Come on, Uncle Saleh, let's see what's left.", 'The door opens: an old desk, a meeting room, and dirt everywhere.', 'This is the studio?!', 'It was the finest studio in the neighbourhood. Now it is up to you to bring it back.', '📌 Tap the dirt to clean it.', 'Start with the floor, then the desk. A clean place lifts your spirit.', '📌 +10 XP.', 'Now the place can breathe. But a studio without content is worth nothing. Go out to the street, talk to people, and film your first interview.'],
  af: ['Pa', 'Oom Saleh', 'Jy', 'My seun, as hierdie opname jou bereik, is ek nie meer by jou nie. Ek laat jou iets kosbaars na: die On Air-ateljee. Dit was my eerste droom, en ek het dit tien jaar gelede gesluit.', 'Oom Saleh het die sleutel. Vat die klein kamera en die mikrofoon in die boks. Dis nie veel nie, maar elke begin is klein.', '📌 Ontvang: klein kamera (vlak 1) en ou mikrofoon (vlak 1).', 'Jy het uiteindelik gekom! Jou pa het gevra dat ek jou self die sleutel gee. Niemand het hierdie plek in tien jaar oopgemaak nie, so maak reg vir die stof.', 'Kom, Oom Saleh, kom ons kyk wat oor is.', "Die deur gaan oop: 'n ou lessenaar, 'n vergaderkamer en vuilgoed oral.", 'Is dít die ateljee?!', 'Dit was die mooiste ateljee in die buurt. Nou is dit aan jou om dit terug te bring.', '📌 Tik op die vuilgoed om dit skoon te maak.', "Begin by die vloer, dan die lessenaar. 'n Skoon plek lig jou gees.", '📌 +10 ervaring.', "Nou kan die plek asemhaal. Maar 'n ateljee sonder inhoud is niks werd nie. Gaan na die straat, praat met mense en verfilm jou eerste onderhoud."],
  sq: ['Babai', 'Xha Salehu', 'Ti', 'Bir, nëse ky regjistrim të arrin, unë nuk jam më me ty. Të lë diçka të çmuar: studion On Air. Ishte ëndrra ime e parë dhe e mbylla dhjetë vjet më parë.', 'Çelësin e ka Xha Salehu. Merr kamerën e vogël dhe mikrofonin në kuti. Nuk janë shumë, por çdo fillim nis i vogël.', '📌 More: kamerë e vogël (niveli 1) dhe mikrofon i vjetër (niveli 1).', 'Më në fund erdhe! Babai yt më tha të ta jap çelësin vetë. Askush s’e ka hapur këtë vend prej dhjetë vjetësh, bëhu gati për pluhurin.', 'Hajde, Xha Saleh, të shohim çfarë ka mbetur.', 'Dera hapet: një tavolinë e vjetër, një sallë mbledhjesh dhe pisllëk kudo.', 'Ky është studioja?!', 'Ishte studioja më e bukur e lagjes. Tani të takon ty ta ringjallësh.', '📌 Prek pisllëkun për ta pastruar.', 'Fillo me dyshemenë, pastaj tavolinën. Një vend i pastër të ngre shpirtin.', '📌 +10 përvojë.', 'Tani vendi merr frymë. Por një studio pa përmbajtje nuk vlen asgjë. Dil në rrugë, fol me njerëzit dhe xhiro intervistën e parë.'],
  bn: ['বাবা', 'সালেহ চাচা', 'তুমি', 'বাবা, এই রেকর্ডিং যদি তোমার কাছে পৌঁছায়, তবে আমি আর তোমার সাথে নেই। তোমার জন্য রেখে গেলাম এক অমূল্য জিনিস: On Air স্টুডিও। এটা ছিল আমার প্রথম স্বপ্ন, দশ বছর আগে বন্ধ করে দিয়েছিলাম।', 'চাবি সালেহ চাচার কাছে। বাক্সের ছোট ক্যামেরা আর মাইক্রোফোনটা নিও। খুব বেশি কিছু না, তবে প্রতিটি শুরু ছোট থেকেই হয়।', '📌 পেয়েছ: ছোট ক্যামেরা (লেভেল ১) আর পুরোনো মাইক্রোফোন (লেভেল ১)।', 'অবশেষে এলে! তোমার বাবা বলেছিলেন চাবিটা যেন নিজের হাতে তোমাকে দিই। দশ বছর কেউ এই জায়গা খোলেনি, ধুলোর জন্য তৈরি হও।', 'চলো সালেহ চাচা, দেখি কী বাকি আছে।', 'দরজা খুলল: একটা পুরোনো ডেস্ক, একটা মিটিং রুম আর সবখানে ময়লা।', 'এটাই স্টুডিও?!', 'এটা ছিল পাড়ার সবচেয়ে সুন্দর স্টুডিও। এখন একে ফিরিয়ে আনা তোমার দায়িত্ব।', '📌 ময়লার উপর ট্যাপ করে পরিষ্কার করো।', 'আগে মেঝে, তারপর ডেস্ক। পরিষ্কার জায়গা মন ভালো করে।', '📌 +১০ অভিজ্ঞতা।', 'এখন জায়গাটা শ্বাস নিচ্ছে। কিন্তু কনটেন্ট ছাড়া স্টুডিওর কোনো মূল্য নেই। রাস্তায় যাও, মানুষের সাথে কথা বলো, প্রথম সাক্ষাৎকার রেকর্ড করো।'],
  bg: ['Татко', 'Чичо Салех', 'Ти', 'Синко, ако този запис стигне до теб, вече не съм с теб. Оставям ти нещо скъпо: студио On Air. Беше първата ми мечта и го затворих преди десет години.', 'Ключът е у чичо Салех. Вземи малката камера и микрофона от кутията. Не са много, но всяко начало е малко.', '📌 Получи: малка камера (ниво 1) и стар микрофон (ниво 1).', 'Най-сетне дойде! Баща ти ме помоли лично да ти дам ключа. Десет години никой не е отварял тук, приготви се за праха.', 'Хайде, чичо Салех, да видим какво е останало.', 'Вратата се отваря: старо бюро, заседателна зала и мръсотия навсякъде.', 'Това ли е студиото?!', 'Беше най-хубавото студио в квартала. Сега от теб зависи да го съживиш.', '📌 Докосни мръсотията, за да я почистиш.', 'Започни с пода, после бюрото. Чистото място вдига духа.', '📌 +10 опит.', 'Сега мястото диша. Но студио без съдържание не струва нищо. Излез на улицата, говори с хората и заснеми първото си интервю.'],
  ca: ['El pare', 'Oncle Saleh', 'Tu', "Fill, si aquesta gravació t'arriba, ja no soc amb tu. Et deixo una cosa preuada: l'estudi On Air. Va ser el meu primer somni i el vaig tancar fa deu anys.", "La clau la té l'oncle Saleh. Agafa la càmera petita i el micròfon de la caixa. No és gaire, però tot comença petit.", '📌 Rebut: càmera petita (nivell 1) i micròfon vell (nivell 1).', "Per fi has vingut! El teu pare em va demanar que et donés la clau en mà. Fa deu anys que ningú obre aquest lloc, prepara't per a la pols.", 'Som-hi, oncle Saleh, a veure què queda.', "La porta s'obre: un escriptori vell, una sala de reunions i brutícia pertot arreu.", 'Això és l’estudi?!', 'Era el millor estudi del barri. Ara et toca a tu fer-lo reviure.', '📌 Toca la brutícia per netejar-la.', "Comença pel terra i després l'escriptori. Un lloc net aixeca l'ànim.", '📌 +10 d’experiència.', 'Ara el lloc respira. Però un estudi sense contingut no val res. Surt al carrer, parla amb la gent i grava la teva primera entrevista.'],
  hr: ['Tata', 'Čika Saleh', 'Ti', 'Sine, ako te ova snimka dočeka, više nisam s tobom. Ostavljam ti nešto dragocjeno: studio On Air. Bio je moj prvi san, a zatvorio sam ga prije deset godina.', 'Ključ je kod čike Saleha. Uzmi malu kameru i mikrofon iz kutije. Nije mnogo, ali svaki početak je malen.', '📌 Primljeno: mala kamera (razina 1) i stari mikrofon (razina 1).', 'Napokon si došao! Tvoj otac me zamolio da ti osobno predam ključ. Deset godina nitko ovo nije otvorio, pripremi se za prašinu.', 'Hajde, čika Saleh, da vidimo što je ostalo.', 'Vrata se otvaraju: stari stol, soba za sastanke i prljavština posvuda.', 'Ovo je studio?!', 'Bio je najljepši studio u kvartu. Sad je na tebi da ga vratiš.', '📌 Dodirni prljavštinu da je očistiš.', 'Počni od poda, pa stol. Čisto mjesto diže duh.', '📌 +10 iskustva.', 'Sad mjesto diše. Ali studio bez sadržaja ne vrijedi ništa. Izađi na ulicu, razgovaraj s ljudima i snimi svoj prvi intervju.'],
  cs: ['Táta', 'Strýček Saleh', 'Ty', 'Synu, jestli se k tobě tahle nahrávka dostane, už nejsem s tebou. Odkazuji ti něco vzácného: studio On Air. Byl to můj první sen a před deseti lety jsem ho zavřel.', 'Klíč má strýček Saleh. Vezmi si malou kameru a mikrofon z krabice. Není to moc, ale každý začátek je malý.', '📌 Získáno: malá kamera (úroveň 1) a starý mikrofon (úroveň 1).', 'Konečně jsi tady! Tvůj otec mě požádal, abych ti klíč předal osobně. Deset let tu nikdo neotevřel, připrav se na prach.', 'Pojďme, strýčku Salehu, podíváme se, co zbylo.', 'Dveře se otevírají: starý stůl, zasedačka a všude špína.', 'Tohle je to studio?!', 'Bylo to nejkrásnější studio ve čtvrti. Teď je na tobě, abys ho vrátil k životu.', '📌 Klepni na špínu a ukliď ji.', 'Začni podlahou, pak stůl. Čisté místo zvedne náladu.', '📌 +10 zkušeností.', 'Teď to tu dýchá. Ale studio bez obsahu nemá cenu. Jdi ven na ulici, mluv s lidmi a natoč svůj první rozhovor.'],
  da: ['Far', 'Onkel Saleh', 'Dig', 'Min søn, hvis denne optagelse når dig, er jeg ikke længere hos dig. Jeg efterlader dig noget dyrebart: On Air-studiet. Det var min første drøm, og jeg lukkede det for ti år siden.', 'Onkel Saleh har nøglen. Tag det lille kamera og mikrofonen i kassen. Det er ikke meget, men enhver begyndelse er lille.', '📌 Modtaget: lille kamera (niveau 1) og gammel mikrofon (niveau 1).', 'Endelig kom du! Din far bad mig give dig nøglen personligt. Ingen har åbnet her i ti år, så gør dig klar til støvet.', 'Kom så, onkel Saleh, lad os se, hvad der er tilbage.', 'Døren åbner: et gammelt skrivebord, et mødelokale og snavs overalt.', 'Er det her studiet?!', 'Det var kvarterets flotteste studie. Nu er det op til dig at bringe det tilbage.', '📌 Tryk på snavset for at gøre rent.', 'Start med gulvet, så skrivebordet. Et rent sted løfter humøret.', '📌 +10 erfaring.', 'Nu kan stedet ånde. Men et studie uden indhold er intet værd. Gå ud på gaden, tal med folk og film dit første interview.'],
  nl: ['Papa', 'Oom Saleh', 'Jij', 'Zoon, als deze opname je bereikt, ben ik niet meer bij je. Ik laat je iets kostbaars na: de On Air-studio. Het was mijn eerste droom, en ik sloot hem tien jaar geleden.', 'Oom Saleh heeft de sleutel. Neem de kleine camera en de microfoon uit de doos. Het is niet veel, maar elk begin is klein.', '📌 Ontvangen: kleine camera (niveau 1) en oude microfoon (niveau 1).', 'Eindelijk ben je er! Je vader vroeg me je de sleutel zelf te geven. Niemand heeft dit in tien jaar geopend, dus bereid je voor op stof.', 'Kom, oom Saleh, we gaan kijken wat er over is.', 'De deur gaat open: een oud bureau, een vergaderkamer en overal vuil.', 'Is dít de studio?!', 'Het was de mooiste studio van de buurt. Nu is het aan jou om hem terug te brengen.', '📌 Tik op het vuil om het schoon te maken.', 'Begin met de vloer, dan het bureau. Een schone plek geeft moed.', '📌 +10 ervaring.', 'Nu kan de plek ademen. Maar een studio zonder content is niets waard. Ga de straat op, praat met mensen en film je eerste interview.'],
  et: ['Isa', 'Saleh-onu', 'Sina', 'Poeg, kui see salvestis sinuni jõuab, pole ma enam sinuga. Jätan sulle midagi kallist: On Airi stuudio. See oli mu esimene unistus ja panin selle kümme aastat tagasi kinni.', 'Võti on Saleh-onu käes. Võta kastist väike kaamera ja mikrofon. Seda pole palju, aga iga algus on väike.', '📌 Saadud: väike kaamera (tase 1) ja vana mikrofon (tase 1).', 'Lõpuks sa tulid! Su isa palus mul võti sulle ise anda. Kümme aastat pole siin keegi käinud, valmistu tolmuks.', 'Lähme, Saleh-onu, vaatame, mis alles on.', 'Uks avaneb: vana laud, koosolekuruum ja mustus kõikjal.', 'See ongi stuudio?!', 'See oli linnaosa kauneim stuudio. Nüüd on sinu kord see tagasi tuua.', '📌 Puuduta mustust, et seda koristada.', 'Alusta põrandast, siis laud. Puhas koht tõstab tuju.', '📌 +10 kogemust.', 'Nüüd saab koht hingata. Aga sisuta stuudio pole midagi väärt. Mine tänavale, räägi inimestega ja filmi oma esimene intervjuu.'],
  fa: ['پدر', 'عمو صالح', 'تو', 'پسرم، اگر این ضبط به دستت رسید، دیگر کنارت نیستم. امانتی برایت دارم: استودیوی «روی آنتن». اولین رؤیای من بود و ده سال پیش بستمش.', 'کلید پیش عمو صالح است. دوربین کوچک و میکروفون داخل جعبه را بردار. چیز زیادی نیست، ولی هر شروعی کوچک است.', '📌 دریافت شد: دوربین کوچک (سطح ۱) و میکروفون قدیمی (سطح ۱).', 'بالاخره آمدی! پدرت سفارش کرد کلید را خودم به دستت بدهم. ده سال است کسی اینجا را باز نکرده، آماده‌ی گرد و خاک باش.', 'برویم عمو صالح، ببینیم چه مانده.', 'در باز می‌شود: یک میز قدیمی، یک اتاق جلسه و کثیفی همه‌جا.', 'این همان استودیوست؟!', 'زیباترین استودیوی محله بود. حالا نوبت توست که زنده‌اش کنی.', '📌 روی کثیفی بزن تا تمیزش کنی.', 'از کف شروع کن، بعد میز. جای تمیز روحیه می‌دهد.', '📌 +۱۰ تجربه.', 'حالا اینجا نفس می‌کشد. ولی استودیو بدون محتوا ارزشی ندارد. برو به خیابان، با مردم حرف بزن و اولین مصاحبه‌ات را بگیر.'],
  fil: ['Itay', 'Tito Saleh', 'Ikaw', 'Anak, kung naabot ka ng recording na ito, wala na ako sa tabi mo. May iiwan akong mahalaga: ang On Air studio. Ito ang una kong pangarap, at isinara ko ito sampung taon na ang nakalipas.', 'Nasa kay Tito Saleh ang susi. Kunin mo ang maliit na kamera at mikropono sa kahon. Hindi gaanong marami, pero lahat ng simula ay maliit.', '📌 Natanggap: maliit na kamera (level 1) at lumang mikropono (level 1).', 'Sa wakas dumating ka! Bilin ng tatay mo na ako mismo ang mag-abot ng susi. Sampung taon nang walang nagbukas dito, maghanda ka sa alikabok.', 'Tara na, Tito Saleh, tingnan natin ang natira.', 'Bumukas ang pinto: isang lumang mesa, isang meeting room, at dumi sa lahat ng dako.', 'Ito ang studio?!', 'Ito ang pinakamagandang studio sa lugar. Ngayon, ikaw na ang magbabalik nito.', '📌 Pindutin ang dumi para linisin.', 'Unahin ang sahig, saka ang mesa. Ang malinis na lugar ay nagpapagaan ng loob.', '📌 +10 XP.', 'Ngayon nakakahinga na ang lugar. Pero walang halaga ang studio na walang content. Lumabas ka sa kalye, kausapin ang mga tao, at i-film ang una mong interview.'],
  fi: ['Isä', 'Saleh-setä', 'Sinä', 'Poikani, jos tämä tallenne tavoittaa sinut, en ole enää kanssasi. Jätän sinulle jotain arvokasta: On Air -studion. Se oli ensimmäinen unelmani, ja suljin sen kymmenen vuotta sitten.', 'Avain on Saleh-sedällä. Ota laatikosta pieni kamera ja mikrofoni. Ei paljon, mutta jokainen alku on pieni.', '📌 Saatu: pieni kamera (taso 1) ja vanha mikrofoni (taso 1).', 'Vihdoin tulit! Isäsi pyysi minua antamaan avaimen sinulle itse. Kukaan ei ole avannut tätä paikkaa kymmeneen vuoteen, valmistaudu pölyyn.', 'Mennään, Saleh-setä, katsotaan mitä on jäljellä.', 'Ovi aukeaa: vanha pöytä, neuvotteluhuone ja likaa kaikkialla.', 'Tämäkö on studio?!', 'Se oli korttelin hienoin studio. Nyt on sinun vuorosi herättää se henkiin.', '📌 Napauta likaa siivotaksesi sen.', 'Aloita lattiasta, sitten pöytä. Puhdas paikka nostaa mielialaa.', '📌 +10 kokemusta.', 'Nyt paikka hengittää. Mutta studio ilman sisältöä ei ole minkään arvoinen. Mene kadulle, puhu ihmisille ja kuvaa ensimmäinen haastattelusi.'],
  fr: ['Papa', 'Oncle Saleh', 'Toi', "Mon fils, si cet enregistrement te parvient, je ne suis plus à tes côtés. Je te confie quelque chose de précieux : le studio On Air. C'était mon premier rêve, et je l'ai fermé il y a dix ans.", "C'est l'oncle Saleh qui a la clé. Prends la petite caméra et le micro dans la boîte. Ce n'est pas grand-chose, mais tout commence petit.", '📌 Reçu : petite caméra (niveau 1) et vieux micro (niveau 1).', "Te voilà enfin ! Ton père m'a demandé de te remettre la clé en main propre. Personne n'a ouvert cet endroit depuis dix ans, prépare-toi à la poussière.", "Allez, oncle Saleh, voyons ce qu'il reste.", "La porte s'ouvre : un vieux bureau, une salle de réunion et de la saleté partout.", "C'est ça, le studio ?!", "C'était le plus beau studio du quartier. Maintenant, c'est à toi de le faire revivre.", '📌 Touche la saleté pour la nettoyer.', 'Commence par le sol, puis le bureau. Un endroit propre remonte le moral.', "📌 +10 d'expérience.", "Maintenant, l'endroit respire. Mais un studio sans contenu ne vaut rien. Sors dans la rue, parle aux gens et filme ta première interview."],
  ka: ['მამა', 'ბიძია სალეჰი', 'შენ', 'შვილო, თუ ეს ჩანაწერი მოგაღწია, მე შენთან აღარ ვარ. გიტოვებ ძვირფას რამეს: სტუდია On Air-ს. ეს ჩემი პირველი ოცნება იყო და ათი წლის წინ დავხურე.', 'გასაღები ბიძია სალეჰთანაა. აიღე პატარა კამერა და მიკროფონი ყუთიდან. ბევრი არაფერია, მაგრამ ყოველი დასაწყისი პატარაა.', '📌 მიიღე: პატარა კამერა (დონე 1) და ძველი მიკროფონი (დონე 1).', 'როგორც იქნა, მოხვედი! მამაშენმა მთხოვა, გასაღები ხელში თავად გადმომეცა. ათი წელია აქ არავის შეუღია, მოემზადე მტვრისთვის.', 'წავედით, ბიძია სალეჰ, ვნახოთ, რა დარჩა.', 'კარი იღება: ძველი მაგიდა, სათათბირო ოთახი და ყველგან ჭუჭყი.', 'ეს არის სტუდია?!', 'უბნის ყველაზე ლამაზი სტუდია იყო. ახლა შენი ჯერია, დააბრუნო.', '📌 შეეხე ჭუჭყს, რომ გაწმინდო.', 'დაიწყე იატაკით, მერე მაგიდა. სუფთა ადგილი სულს უმაღლებს.', '📌 +10 გამოცდილება.', 'ახლა ადგილი სუნთქავს. მაგრამ კონტენტის გარეშე სტუდია არაფრად ღირს. გადი ქუჩაში, ესაუბრე ხალხს და გადაიღე პირველი ინტერვიუ.'],
  de: ['Papa', 'Onkel Saleh', 'Du', 'Mein Sohn, wenn dich diese Aufnahme erreicht, bin ich nicht mehr bei dir. Ich vertraue dir etwas Kostbares an: das On-Air-Studio. Es war mein erster Traum, und ich habe es vor zehn Jahren geschlossen.', 'Onkel Saleh hat den Schlüssel. Nimm die kleine Kamera und das Mikrofon aus der Kiste. Es ist nicht viel, aber jeder Anfang ist klein.', '📌 Erhalten: kleine Kamera (Stufe 1) und altes Mikrofon (Stufe 1).', 'Endlich bist du da! Dein Vater bat mich, dir den Schlüssel persönlich zu geben. Seit zehn Jahren war hier niemand drin, mach dich auf Staub gefasst.', 'Komm, Onkel Saleh, schauen wir, was übrig ist.', 'Die Tür geht auf: ein alter Schreibtisch, ein Besprechungsraum und überall Dreck.', 'Das ist das Studio?!', 'Es war das schönste Studio im Viertel. Jetzt liegt es an dir, es zurückzubringen.', '📌 Tippe auf den Dreck, um ihn zu putzen.', 'Fang mit dem Boden an, dann der Schreibtisch. Ein sauberer Ort hebt die Stimmung.', '📌 +10 Erfahrung.', 'Jetzt kann der Ort atmen. Aber ein Studio ohne Inhalte ist nichts wert. Geh auf die Straße, sprich mit Leuten und dreh dein erstes Interview.'],
  el: ['Μπαμπάς', 'Θείος Σάλεχ', 'Εσύ', 'Γιε μου, αν σε φτάσει αυτή η ηχογράφηση, δεν είμαι πια μαζί σου. Σου αφήνω κάτι πολύτιμο: το στούντιο On Air. Ήταν το πρώτο μου όνειρο και το έκλεισα πριν από δέκα χρόνια.', 'Το κλειδί το έχει ο θείος Σάλεχ. Πάρε τη μικρή κάμερα και το μικρόφωνο από το κουτί. Δεν είναι πολλά, αλλά κάθε αρχή είναι μικρή.', '📌 Παρέλαβες: μικρή κάμερα (επίπεδο 1) και παλιό μικρόφωνο (επίπεδο 1).', 'Επιτέλους ήρθες! Ο πατέρας σου μου ζήτησε να σου δώσω το κλειδί στο χέρι. Δέκα χρόνια δεν το άνοιξε κανείς, ετοιμάσου για σκόνη.', 'Πάμε, θείε Σάλεχ, να δούμε τι έμεινε.', 'Η πόρτα ανοίγει: ένα παλιό γραφείο, μια αίθουσα συσκέψεων και βρωμιά παντού.', 'Αυτό είναι το στούντιο;!', 'Ήταν το ωραιότερο στούντιο της γειτονιάς. Τώρα είναι στο χέρι σου να το ξαναζωντανέψεις.', '📌 Πάτα τη βρωμιά για να την καθαρίσεις.', 'Ξεκίνα από το πάτωμα, μετά το γραφείο. Ένας καθαρός χώρος ανεβάζει τη διάθεση.', '📌 +10 εμπειρία.', 'Τώρα ο χώρος ανασαίνει. Αλλά ένα στούντιο χωρίς περιεχόμενο δεν αξίζει τίποτα. Βγες στον δρόμο, μίλα με τον κόσμο και γύρισε την πρώτη σου συνέντευξη.'],
  ht: ['Papa', 'Tonton Saleh', 'Ou', 'Pitit mwen, si anrejistreman sa a rive jwenn ou, mwen pa la avè w ankò. Mwen kite yon bagay ki gen anpil valè pou ou: estidyo On Air la. Se te premye rèv mwen, e mwen te fèmen l sa gen dizan.', 'Se Tonton Saleh ki gen kle a. Pran ti kamera a ak mikwo a ki nan bwat la. Se pa anpil, men tout kòmansman piti.', '📌 Ou resevwa: ti kamera (nivo 1) ak vye mikwo (nivo 1).', 'Finalman ou vini! Papa w te mande m remèt ou kle a nan men w. Sa gen dizan pèsonn pa louvri isit la, pare pou pousyè.', 'Ann ale, Tonton Saleh, ann wè sa ki rete.', 'Pòt la louvri: yon vye biwo, yon sal reyinyon ak salte toupatou.', 'Se sa ki estidyo a?!', 'Se te pi bèl estidyo nan katye a. Kounye a se ou ki pou fè l reviv.', '📌 Peze sou salte a pou netwaye l.', 'Kòmanse ak atè a, apre biwo a. Yon kote ki pwòp leve moral ou.', '📌 +10 eksperyans.', 'Kounye a kote a ka respire. Men yon estidyo san kontni pa vo anyen. Ale nan lari a, pale ak moun, epi filme premye entèvyou w.'],
  he: ['אבא', 'הדוד סאלח', 'אתה', 'בני, אם ההקלטה הזאת הגיעה אליך, אני כבר לא איתך. אני משאיר לך דבר יקר: אולפן On Air. זה היה החלום הראשון שלי, וסגרתי אותו לפני עשר שנים.', 'המפתח אצל הדוד סאלח. קח את המצלמה הקטנה ואת המיקרופון שבקופסה. זה לא הרבה, אבל כל התחלה היא קטנה.', '📌 קיבלת: מצלמה קטנה (רמה 1) ומיקרופון ישן (רמה 1).', 'סוף סוף הגעת! אבא שלך ביקש שאמסור לך את המפתח ביד. עשר שנים אף אחד לא פתח כאן, תתכונן לאבק.', 'יאללה, דוד סאלח, בוא נראה מה נשאר.', 'הדלת נפתחת: שולחן ישן, חדר ישיבות ולכלוך בכל מקום.', 'זה האולפן?!', 'זה היה האולפן הכי יפה בשכונה. עכשיו תורך להחזיר אותו לחיים.', '📌 הקש על הלכלוך כדי לנקות אותו.', 'תתחיל מהרצפה, אחר כך השולחן. מקום נקי מרים את מצב הרוח.', '📌 +10 ניסיון.', 'עכשיו המקום נושם. אבל אולפן בלי תוכן לא שווה כלום. צא לרחוב, דבר עם אנשים וצלם את הראיון הראשון שלך.'],
  hi: ['पिता', 'सालेह चाचा', 'आप', 'बेटा, अगर यह रिकॉर्डिंग तुम तक पहुँची है, तो मैं अब तुम्हारे साथ नहीं हूँ। तुम्हारे लिए एक अनमोल चीज़ छोड़ रहा हूँ: On Air स्टूडियो। यह मेरा पहला सपना था, और दस साल पहले मैंने इसे बंद कर दिया।', 'चाबी सालेह चाचा के पास है। बॉक्स से छोटा कैमरा और माइक ले लेना। ज़्यादा नहीं है, पर हर शुरुआत छोटी होती है।', '📌 मिला: छोटा कैमरा (लेवल 1) और पुराना माइक (लेवल 1)।', 'आख़िरकार तुम आ गए! तुम्हारे पिता ने कहा था कि चाबी मैं ख़ुद तुम्हारे हाथ में दूँ। दस साल से किसी ने यह जगह नहीं खोली, धूल के लिए तैयार रहो।', 'चलिए सालेह चाचा, देखें क्या बचा है।', 'दरवाज़ा खुलता है: एक पुरानी मेज़, एक मीटिंग रूम और हर तरफ़ गंदगी।', 'यही स्टूडियो है?!', 'यह मोहल्ले का सबसे सुंदर स्टूडियो था। अब इसे वापस लाना तुम्हारे हाथ में है।', '📌 गंदगी पर टैप करके उसे साफ़ करें।', 'पहले फ़र्श, फिर मेज़। साफ़ जगह मन को ऊँचा करती है।', '📌 +10 अनुभव।', 'अब जगह साँस ले रही है। पर बिना कंटेंट के स्टूडियो की कोई क़ीमत नहीं। सड़क पर जाओ, लोगों से बात करो और अपना पहला इंटरव्यू रिकॉर्ड करो।'],
  te: ['నాన్న', 'సాలెహ్ బాబాయ్', 'మీరు', 'బాబూ, ఈ రికార్డింగ్ నీకు చేరితే, నేను ఇక నీతో లేను. నీకు ఒక విలువైనది వదిలి వెళ్తున్నా: On Air స్టూడియో. అది నా మొదటి కల, పదేళ్ల క్రితం మూసేశాను.', 'తాళం చెవి సాలెహ్ బాబాయ్ దగ్గర ఉంది. పెట్టెలోని చిన్న కెమెరా, మైక్ తీసుకో. ఎక్కువేమీ కాదు, కానీ ప్రతి మొదలు చిన్నదే.', '📌 అందుకున్నావు: చిన్న కెమెరా (లెవెల్ 1), పాత మైక్ (లెవెల్ 1).', 'ఎట్టకేలకు వచ్చావు! తాళం నీ చేతికే ఇవ్వమని మీ నాన్న చెప్పారు. పదేళ్లుగా ఎవరూ ఇది తెరవలేదు, దుమ్ముకు సిద్ధంగా ఉండు.', 'పదండి సాలెహ్ బాబాయ్, ఏం మిగిలిందో చూద్దాం.', 'తలుపు తెరుచుకుంది: పాత బల్ల, ఒక మీటింగ్ గది, ఎక్కడ చూసినా మురికి.', 'ఇదేనా స్టూడియో?!', 'ఇది మన వీధిలోనే అందమైన స్టూడియో. ఇప్పుడు దాన్ని తిరిగి తీసుకురావడం నీ బాధ్యత.', '📌 మురికిని శుభ్రం చేయడానికి దానిపై తట్టండి.', 'ముందు నేల, తర్వాత బల్ల. శుభ్రమైన చోటు మనసును ఉత్సాహపరుస్తుంది.', '📌 +10 అనుభవం.', 'ఇప్పుడు ఈ చోటు ఊపిరి పీల్చుకుంటోంది. కానీ కంటెంట్ లేని స్టూడియోకు విలువ లేదు. వీధిలోకి వెళ్లు, మనుషులతో మాట్లాడు, నీ మొదటి ఇంటర్వ్యూ తీయి.'],
  hu: ['Apa', 'Szaleh bácsi', 'Te', 'Fiam, ha ez a felvétel eljut hozzád, már nem vagyok veled. Valami értékeset hagyok rád: az On Air stúdiót. Ez volt az első álmom, és tíz éve bezártam.', 'A kulcs Szaleh bácsinál van. Vidd el a kis kamerát és a mikrofont a dobozból. Nem sok, de minden kezdet kicsi.', '📌 Kaptál: kis kamera (1. szint) és régi mikrofon (1. szint).', 'Végre megjöttél! Apád megkért, hogy személyesen adjam át a kulcsot. Tíz éve senki sem nyitotta ki, készülj a porra.', 'Gyerünk, Szaleh bácsi, nézzük, mi maradt.', 'Kinyílik az ajtó: egy régi asztal, egy tárgyaló és mindenhol kosz.', 'Ez a stúdió?!', 'A környék legszebb stúdiója volt. Most rajtad a sor, hogy visszahozd.', '📌 Koppints a koszra a takarításhoz.', 'Kezdd a padlóval, aztán az asztal. A tiszta hely feldobja a hangulatot.', '📌 +10 tapasztalat.', 'Most már lélegzik a hely. De egy stúdió tartalom nélkül semmit sem ér. Menj ki az utcára, beszélgess az emberekkel, és vedd fel az első interjúdat.'],
  id: ['Ayah', 'Paman Saleh', 'Kamu', 'Nak, kalau rekaman ini sampai kepadamu, Ayah sudah tidak bersamamu. Ayah titipkan sesuatu yang berharga: studio On Air. Itu mimpi pertama Ayah, dan Ayah menutupnya sepuluh tahun lalu.', 'Kuncinya ada pada Paman Saleh. Ambil kamera kecil dan mikrofon di dalam kotak. Tidak banyak, tapi setiap awal dimulai dari kecil.', '📌 Diterima: kamera kecil (level 1) dan mikrofon tua (level 1).', 'Akhirnya kamu datang! Ayahmu berpesan agar aku sendiri yang menyerahkan kunci ini. Sudah sepuluh tahun tak ada yang membukanya, bersiaplah dengan debu.', 'Ayo, Paman Saleh, kita lihat apa yang tersisa.', 'Pintu terbuka: meja tua, ruang rapat, dan kotoran di mana-mana.', 'Ini studionya?!', 'Dulu ini studio terbaik di lingkungan ini. Sekarang giliranmu menghidupkannya kembali.', '📌 Ketuk kotorannya untuk membersihkan.', 'Mulai dari lantai, lalu meja. Tempat yang bersih membangkitkan semangat.', '📌 +10 XP.', 'Sekarang tempat ini bisa bernapas. Tapi studio tanpa konten tak ada nilainya. Turun ke jalan, ajak orang bicara, dan rekam wawancara pertamamu.'],
  it: ['Papà', 'Zio Saleh', 'Tu', "Figlio mio, se questa registrazione ti raggiunge, io non sono più con te. Ti affido qualcosa di prezioso: lo studio On Air. È stato il mio primo sogno, e l'ho chiuso dieci anni fa.", 'La chiave ce l’ha lo zio Saleh. Prendi la piccola telecamera e il microfono nella scatola. Non è molto, ma ogni inizio è piccolo.', '📌 Ricevuto: piccola telecamera (livello 1) e vecchio microfono (livello 1).', 'Finalmente sei arrivato! Tuo padre mi ha chiesto di darti la chiave di persona. Nessuno ha aperto questo posto da dieci anni, preparati alla polvere.', 'Andiamo, zio Saleh, vediamo cosa è rimasto.', 'La porta si apre: una vecchia scrivania, una sala riunioni e sporco ovunque.', 'Questo è lo studio?!', 'Era lo studio più bello del quartiere. Ora tocca a te riportarlo in vita.', '📌 Tocca lo sporco per pulirlo.', "Inizia dal pavimento, poi la scrivania. Un posto pulito tira su il morale.", '📌 +10 esperienza.', 'Ora il posto respira. Ma uno studio senza contenuti non vale niente. Esci in strada, parla con la gente e gira la tua prima intervista.'],
  ja: ['父', 'サーレハおじさん', 'あなた', '息子よ、この録音が届いたなら、私はもうそばにいない。大切なものを託す。「On Air」スタジオだ。私の最初の夢で、十年前に閉めてしまった。', '鍵はサーレハおじさんが持っている。箱の中の小さなカメラとマイクを持っていきなさい。大したものではないが、どんな始まりも小さいものだ。', '📌 入手：小さなカメラ（レベル1）と古いマイク（レベル1）。', 'やっと来たか！お父さんに、鍵は直接手渡すよう頼まれていたんだ。十年も誰も開けていないから、ほこりは覚悟しておけ。', '行こう、サーレハおじさん。何が残っているか見よう。', 'ドアが開く。古い机、会議室、そしてあちこちに汚れ。', 'これがスタジオ？！', 'この辺りで一番のスタジオだったんだ。これからはお前が蘇らせる番だ。', '📌 汚れをタップして掃除しよう。', 'まず床から、次に机だ。きれいな場所は気分を上げてくれる。', '📌 +10 経験値。', 'これで場所が息を吹き返した。だが、中身のないスタジオに価値はない。街へ出て、人と話し、最初のインタビューを撮ってこい。'],
  ko: ['아버지', '살레 아저씨', '나', '아들아, 이 녹음이 너에게 닿았다면 나는 더 이상 네 곁에 없단다. 소중한 것을 남긴다. 바로 On Air 스튜디오다. 내 첫 번째 꿈이었고, 십 년 전에 문을 닫았지.', '열쇠는 살레 아저씨가 갖고 있다. 상자 안의 작은 카메라와 마이크를 챙겨라. 별것 아니지만, 모든 시작은 작단다.', '📌 획득: 작은 카메라(레벨 1)와 낡은 마이크(레벨 1).', '드디어 왔구나! 네 아버지가 열쇠를 직접 건네 달라고 부탁했단다. 십 년 동안 아무도 열지 않았으니 먼지는 각오해라.', '가요, 살레 아저씨. 뭐가 남았는지 봐요.', '문이 열린다. 낡은 책상, 회의실, 그리고 사방에 먼지와 쓰레기.', '이게 스튜디오라고요?!', '동네에서 제일 멋진 스튜디오였지. 이제 네가 되살릴 차례다.', '📌 더러운 곳을 탭해서 청소하세요.', '바닥부터 하고, 그다음 책상이다. 깨끗한 곳이 기분을 올려 준단다.', '📌 경험치 +10.', '이제야 숨을 쉬는구나. 하지만 콘텐츠 없는 스튜디오는 아무 가치가 없다. 거리로 나가 사람들과 이야기하고 첫 인터뷰를 찍어 와라.'],
  ku: ['Bav', 'Mamê Salih', 'Tu', 'Kurê min, eger ev tomar gihîşt te, ez êdî ne bi te re me. Ji te re tiştekî bi qîmet dihêlim: stûdyoya On Air. Ew xewna min a yekem bû, û min deh sal berê ew girt.', 'Mifte li cem Mamê Salih e. Kameraya biçûk û mîkrofona di qutiyê de bigire. Ne zêde ye, lê her destpêk biçûk e.', '📌 Hat wergirtin: kameraya biçûk (asta 1) û mîkrofona kevn (asta 1).', 'Di dawiyê de tu hatî! Bavê te ji min xwest ku ez mifteyê bi destê xwe bidim te. Deh sal in kesî ev der venekiriye, xwe ji tozê re amade bike.', 'Werin, Mamê Salih, em binêrin ka çi maye.', 'Derî vedibe: maseyeke kevn, odeyeke civînê û qirêjî li her derê.', 'Stûdyo ev e?!', 'Stûdyoya herî xweşik a taxê bû. Niha dora te ye ku tu wê vegerînî.', '📌 Li ser qirêjiyê bitikîne da ku paqij bikî.', 'Ji erdê dest pê bike, paşê mase. Cihê paqij giyanê te bilind dike.', '📌 +10 ezmûn.', 'Niha der bêhna xwe digire. Lê stûdyoya bê naverok bi tiştekî nayê. Derkeve kolanê, bi xelkê re bipeyive û hevpeyvîna xwe ya yekem bikişîne.'],
  lv: ['Tētis', 'Tēvocis Salehs', 'Tu', 'Dēls, ja šis ieraksts tevi sasniedz, es vairs neesmu ar tevi. Atstāju tev ko dārgu: On Air studiju. Tas bija mans pirmais sapnis, un pirms desmit gadiem es to aizvēru.', 'Atslēga ir tēvocim Saleham. Paņem mazo kameru un mikrofonu no kastes. Tas nav daudz, bet katrs sākums ir mazs.', '📌 Saņemts: maza kamera (1. līmenis) un vecs mikrofons (1. līmenis).', 'Beidzot tu atnāci! Tavs tēvs lūdza atslēgu tev iedot personīgi. Desmit gadus neviens šeit nav vēris durvis, gatavojies putekļiem.', 'Ejam, tēvoci Saleh, paskatīsimies, kas palicis.', 'Durvis atveras: vecs galds, sanāksmju telpa un visur netīrumi.', 'Šī ir studija?!', 'Tā bija skaistākā studija apkaimē. Tagad tavs gājiens to atdzīvināt.', '📌 Pieskaries netīrumiem, lai tos notīrītu.', 'Sāc ar grīdu, tad galdu. Tīra vieta paceļ garastāvokli.', '📌 +10 pieredze.', 'Tagad vieta elpo. Bet studija bez satura neko nav vērta. Ej uz ielas, runā ar cilvēkiem un nofilmē savu pirmo interviju.'],
  lt: ['Tėtis', 'Dėdė Salehas', 'Tu', 'Sūnau, jei šis įrašas tave pasiekė, manęs jau nebėra šalia. Palieku tau brangų dalyką: studiją On Air. Tai buvo mano pirmoji svajonė, o prieš dešimt metų ją uždariau.', 'Raktas pas dėdę Salehą. Pasiimk mažą kamerą ir mikrofoną iš dėžės. Nedaug, bet kiekviena pradžia maža.', '📌 Gauta: maža kamera (1 lygis) ir senas mikrofonas (1 lygis).', 'Pagaliau atvykai! Tavo tėvas prašė raktą tau įteikti asmeniškai. Dešimt metų niekas čia neatidarė, pasiruošk dulkėms.', 'Einam, dėde Salehai, pažiūrėkim, kas liko.', 'Durys atsidaro: senas stalas, posėdžių kambarys ir visur purvas.', 'Tai čia studija?!', 'Tai buvo gražiausia studija rajone. Dabar tavo eilė ją prikelti.', '📌 Paliesk purvą, kad jį išvalytum.', 'Pradėk nuo grindų, paskui stalas. Švari vieta pakelia nuotaiką.', '📌 +10 patirties.', 'Dabar vieta kvėpuoja. Bet studija be turinio nieko neverta. Eik į gatvę, kalbėkis su žmonėmis ir nufilmuok pirmąjį interviu.'],
  mk: ['Тато', 'Чичко Салех', 'Ти', 'Сине, ако оваа снимка стигне до тебе, јас веќе не сум со тебе. Ти оставам нешто скапоцено: студиото On Air. Тоа беше мојот прв сон, а го затворив пред десет години.', 'Клучот е кај чичко Салех. Земи ја малата камера и микрофонот од кутијата. Не е многу, но секој почеток е мал.', '📌 Добиено: мала камера (ниво 1) и стар микрофон (ниво 1).', 'Конечно дојде! Татко ти ме замоли лично да ти го дадам клучот. Десет години никој не го отворил ова место, подготви се за прашина.', 'Ајде, чичко Салех, да видиме што остана.', 'Вратата се отвора: стара маса, сала за состаноци и нечистотија насекаде.', 'Ова ли е студиото?!', 'Беше најубавото студио во маалото. Сега е твој ред да го вратиш.', '📌 Допри ја нечистотијата за да ја исчистиш.', 'Почни од подот, па масата. Чисто место го крева духот.', '📌 +10 искуство.', 'Сега местото дише. Но студио без содржина не вреди ништо. Излези на улица, зборувај со луѓето и снимај го првото интервју.'],
  ms: ['Ayah', 'Pak Cik Saleh', 'Anda', 'Anakku, jika rakaman ini sampai kepadamu, ayah sudah tiada di sisimu. Ayah tinggalkan sesuatu yang berharga: studio On Air. Itu impian pertama ayah, dan ayah menutupnya sepuluh tahun lalu.', 'Kuncinya ada pada Pak Cik Saleh. Ambil kamera kecil dan mikrofon dalam kotak. Tidak banyak, tetapi setiap permulaan itu kecil.', '📌 Diterima: kamera kecil (tahap 1) dan mikrofon lama (tahap 1).', 'Akhirnya kamu datang! Ayahmu berpesan supaya aku sendiri serahkan kunci ini. Sudah sepuluh tahun tiada siapa membukanya, bersedialah dengan habuk.', 'Mari, Pak Cik Saleh, kita tengok apa yang tinggal.', 'Pintu terbuka: meja lama, bilik mesyuarat dan kotoran di mana-mana.', 'Inikah studionya?!', 'Dulu inilah studio terbaik di kawasan ini. Kini giliran kamu menghidupkannya semula.', '📌 Ketik kotoran untuk membersihkannya.', 'Mula dengan lantai, kemudian meja. Tempat yang bersih menaikkan semangat.', '📌 +10 XP.', 'Sekarang tempat ini boleh bernafas. Tetapi studio tanpa kandungan tiada nilainya. Turun ke jalan, berbual dengan orang ramai dan rakam temu bual pertamamu.'],
  ml: ['അച്ഛൻ', 'സാലിഹ് അമ്മാവൻ', 'നിങ്ങൾ', 'മോനേ, ഈ റെക്കോർഡിംഗ് നിന്റെ കയ്യിലെത്തിയാൽ, ഞാൻ ഇനി നിന്നോടൊപ്പമില്ല. വിലപ്പെട്ട ഒന്ന് നിനക്കായി വിടുന്നു: On Air സ്റ്റുഡിയോ. അത് എന്റെ ആദ്യ സ്വപ്നമായിരുന്നു, പത്തു വർഷം മുമ്പ് ഞാൻ അത് അടച്ചു.', 'താക്കോൽ സാലിഹ് അമ്മാവന്റെ കയ്യിലുണ്ട്. പെട്ടിയിലെ ചെറിയ ക്യാമറയും മൈക്കും എടുത്തോ. അധികമൊന്നുമില്ല, പക്ഷേ എല്ലാ തുടക്കവും ചെറുതാണ്.', '📌 ലഭിച്ചു: ചെറിയ ക്യാമറ (ലെവൽ 1), പഴയ മൈക്ക് (ലെവൽ 1).', 'ഒടുവിൽ നീ വന്നു! താക്കോൽ നിന്റെ കയ്യിൽ തന്നെ തരാൻ നിന്റെ അച്ഛൻ ഏൽപ്പിച്ചിരുന്നു. പത്തു വർഷമായി ആരും ഇത് തുറന്നിട്ടില്ല, പൊടിക്ക് തയ്യാറായിക്കോ.', 'വരൂ സാലിഹ് അമ്മാവാ, എന്താണ് ബാക്കിയുള്ളതെന്ന് നോക്കാം.', 'വാതിൽ തുറക്കുന്നു: ഒരു പഴയ മേശ, ഒരു മീറ്റിംഗ് മുറി, എല്ലായിടത്തും അഴുക്ക്.', 'ഇതാണോ സ്റ്റുഡിയോ?!', 'ഈ നാട്ടിലെ ഏറ്റവും മനോഹരമായ സ്റ്റുഡിയോ ആയിരുന്നു. ഇനി അതിനെ തിരികെ കൊണ്ടുവരുന്നത് നിന്റെ ഊഴം.', '📌 വൃത്തിയാക്കാൻ അഴുക്കിൽ ടാപ്പ് ചെയ്യുക.', 'ആദ്യം തറ, പിന്നെ മേശ. വൃത്തിയുള്ള സ്ഥലം മനസ്സിന് ഉണർവ് നൽകും.', '📌 +10 അനുഭവം.', 'ഇപ്പോൾ ഈ സ്ഥലം ശ്വസിക്കുന്നു. പക്ഷേ ഉള്ളടക്കമില്ലാത്ത സ്റ്റുഡിയോയ്ക്ക് വിലയില്ല. തെരുവിലേക്ക് പോകൂ, ആളുകളോട് സംസാരിക്കൂ, നിന്റെ ആദ്യ അഭിമുഖം ചിത്രീകരിക്കൂ.'],
  ne: ['बुबा', 'सालेह काका', 'तपाईं', 'छोरा, यो रेकर्डिङ तिमीसम्म पुगे म अब तिम्रो साथमा छैन। तिम्रो लागि एउटा अमूल्य कुरा छोड्दैछु: On Air स्टुडियो। यो मेरो पहिलो सपना थियो, र दस वर्षअघि मैले यसलाई बन्द गरेँ।', 'साँचो सालेह काकासँग छ। बाकसको सानो क्यामेरा र माइक लैजाऊ। धेरै होइन, तर हरेक सुरुवात सानै हुन्छ।', '📌 पाइयो: सानो क्यामेरा (लेभल १) र पुरानो माइक (लेभल १)।', 'अन्ततः तिमी आयौ! तिम्रो बुबाले साँचो आफ्नै हातले दिन भन्नुभएको थियो। दस वर्षदेखि यहाँ कसैले खोलेको छैन, धुलोका लागि तयार होऊ।', 'जाऔँ सालेह काका, के बाँकी छ हेरौँ।', 'ढोका खुल्छ: एउटा पुरानो टेबल, एउटा बैठक कोठा, र जताततै फोहोर।', 'यही हो स्टुडियो?!', 'यो टोलको सबैभन्दा राम्रो स्टुडियो थियो। अब यसलाई फर्काउने पालो तिम्रो।', '📌 सफा गर्न फोहोरमा ट्याप गर्नुहोस्।', 'पहिला भुइँ, अनि टेबल। सफा ठाउँले मन उज्यालो बनाउँछ।', '📌 +१० अनुभव।', 'अब यो ठाउँले सास फेर्दैछ। तर सामग्रीबिनाको स्टुडियोको कुनै मूल्य छैन। सडकमा जाऊ, मानिससँग कुरा गर र पहिलो अन्तर्वार्ता खिच।'],
  no: ['Pappa', 'Onkel Saleh', 'Du', 'Sønnen min, hvis dette opptaket når deg, er jeg ikke lenger hos deg. Jeg etterlater deg noe dyrebart: On Air-studioet. Det var min første drøm, og jeg stengte det for ti år siden.', 'Onkel Saleh har nøkkelen. Ta det lille kameraet og mikrofonen i esken. Det er ikke mye, men hver begynnelse er liten.', '📌 Mottatt: lite kamera (nivå 1) og gammel mikrofon (nivå 1).', 'Endelig kom du! Faren din ba meg gi deg nøkkelen selv. Ingen har åpnet her på ti år, så gjør deg klar for støv.', 'Kom igjen, onkel Saleh, la oss se hva som er igjen.', 'Døren åpnes: et gammelt skrivebord, et møterom og skitt overalt.', 'Er dette studioet?!', 'Det var nabolagets fineste studio. Nå er det opp til deg å bringe det tilbake.', '📌 Trykk på skitten for å vaske den bort.', 'Begynn med gulvet, så skrivebordet. Et rent sted løfter humøret.', '📌 +10 erfaring.', 'Nå kan stedet puste. Men et studio uten innhold er ingenting verdt. Gå ut på gaten, snakk med folk og film ditt første intervju.'],
  pl: ['Tata', 'Wujek Saleh', 'Ty', 'Synu, jeśli to nagranie do ciebie dotrze, nie ma mnie już przy tobie. Zostawiam ci coś cennego: studio On Air. To było moje pierwsze marzenie, a zamknąłem je dziesięć lat temu.', 'Klucz ma wujek Saleh. Weź małą kamerę i mikrofon z pudełka. To niewiele, ale każdy początek jest mały.', '📌 Otrzymano: mała kamera (poziom 1) i stary mikrofon (poziom 1).', 'Nareszcie przyszedłeś! Twój ojciec prosił, żebym osobiście dał ci klucz. Od dziesięciu lat nikt tu nie zaglądał, przygotuj się na kurz.', 'Chodźmy, wujku Salehu, zobaczmy, co zostało.', 'Drzwi się otwierają: stare biurko, sala konferencyjna i wszędzie brud.', 'To jest to studio?!', 'Było najpiękniejszym studiem w okolicy. Teraz twoja kolej, by je ożywić.', '📌 Dotknij brudu, żeby go posprzątać.', 'Zacznij od podłogi, potem biurko. Czyste miejsce podnosi na duchu.', '📌 +10 doświadczenia.', 'Teraz to miejsce oddycha. Ale studio bez treści nic nie jest warte. Wyjdź na ulicę, rozmawiaj z ludźmi i nagraj swój pierwszy wywiad.'],
  pt: ['Pai', 'Tio Saleh', 'Você', 'Filho, se esta gravação chegar até você, eu já não estou ao seu lado. Deixo algo precioso para você: o estúdio On Air. Foi o meu primeiro sonho, e eu o fechei há dez anos.', 'A chave está com o tio Saleh. Pegue a câmera pequena e o microfone da caixa. Não é muito, mas todo começo é pequeno.', '📌 Recebido: câmera pequena (nível 1) e microfone velho (nível 1).', 'Finalmente você veio! Seu pai me pediu para entregar a chave em mãos. Ninguém abre este lugar há dez anos, prepare-se para a poeira.', 'Vamos, tio Saleh, ver o que sobrou.', 'A porta se abre: uma mesa velha, uma sala de reuniões e sujeira por toda parte.', 'Isso é o estúdio?!', 'Era o estúdio mais bonito do bairro. Agora é a sua vez de trazê-lo de volta.', '📌 Toque na sujeira para limpar.', 'Comece pelo chão, depois a mesa. Um lugar limpo levanta o ânimo.', '📌 +10 de experiência.', 'Agora o lugar respira. Mas um estúdio sem conteúdo não vale nada. Vá para a rua, converse com as pessoas e grave sua primeira entrevista.'],
  ro: ['Tata', 'Unchiul Saleh', 'Tu', 'Fiule, dacă această înregistrare ajunge la tine, eu nu mai sunt alături de tine. Îți las ceva prețios: studioul On Air. A fost primul meu vis și l-am închis acum zece ani.', 'Cheia o are unchiul Saleh. Ia camera mică și microfonul din cutie. Nu e mult, dar orice început e mic.', '📌 Primit: cameră mică (nivelul 1) și microfon vechi (nivelul 1).', 'În sfârșit ai venit! Tatăl tău m-a rugat să-ți dau cheia în mână. De zece ani n-a mai deschis nimeni aici, pregătește-te de praf.', 'Haide, unchiule Saleh, să vedem ce a mai rămas.', 'Ușa se deschide: un birou vechi, o sală de ședințe și murdărie peste tot.', 'Acesta e studioul?!', 'Era cel mai frumos studio din cartier. Acum e rândul tău să-l readuci la viață.', '📌 Atinge murdăria ca să o cureți.', 'Începe cu podeaua, apoi biroul. Un loc curat îți ridică moralul.', '📌 +10 experiență.', 'Acum locul respiră. Dar un studio fără conținut nu valorează nimic. Ieși în stradă, vorbește cu oamenii și filmează primul tău interviu.'],
  ru: ['Отец', 'Дядя Салех', 'Ты', 'Сынок, если эта запись дошла до тебя, меня уже нет рядом. Оставляю тебе нечто ценное: студию On Air. Это была моя первая мечта, и десять лет назад я её закрыл.', 'Ключ у дяди Салеха. Возьми маленькую камеру и микрофон из коробки. Это немного, но любое начало бывает малым.', '📌 Получено: маленькая камера (уровень 1) и старый микрофон (уровень 1).', 'Наконец-то ты пришёл! Твой отец просил отдать тебе ключ лично. Десять лет сюда никто не заходил, готовься к пыли.', 'Пойдём, дядя Салех, посмотрим, что осталось.', 'Дверь открывается: старый стол, переговорная и грязь повсюду.', 'Это и есть студия?!', 'Это была лучшая студия в районе. Теперь твоя очередь её возродить.', '📌 Нажимай на грязь, чтобы убрать её.', 'Начни с пола, потом стол. Чистое место поднимает настроение.', '📌 +10 опыта.', 'Теперь здесь можно дышать. Но студия без контента ничего не стоит. Выйди на улицу, поговори с людьми и сними своё первое интервью.'],
  sr: ['Тата', 'Чика Салех', 'Ти', 'Сине, ако те овај снимак стигне, ја више нисам с тобом. Остављам ти нешто драгоцено: студио On Air. Био је мој први сан, а затворио сам га пре десет година.', 'Кључ је код чика Салеха. Узми малу камеру и микрофон из кутије. Није много, али сваки почетак је мали.', '📌 Добијено: мала камера (ниво 1) и стари микрофон (ниво 1).', 'Коначно си дошао! Твој отац ме замолио да ти лично предам кључ. Десет година нико није отварао, спреми се за прашину.', 'Хајде, чика Салех, да видимо шта је остало.', 'Врата се отварају: стари сто, сала за састанке и прљавштина свуда.', 'Ово је студио?!', 'Био је најлепши студио у крају. Сада је на теби да га вратиш.', '📌 Додирни прљавштину да је очистиш.', 'Почни од пода, па сто. Чисто место подиже дух.', '📌 +10 искуства.', 'Сада место дише. Али студио без садржаја не вреди ништа. Изађи на улицу, разговарај са људима и сними свој први интервју.'],
  'zh-Hans': ['父亲', '萨利赫叔叔', '你', '孩子，如果你收到这段录音，我已经不在你身边了。我留给你一样珍贵的东西：On Air 演播室。那是我的第一个梦想，十年前我把它关了。', '钥匙在萨利赫叔叔那里。带上盒子里的小摄像机和麦克风。东西不多，但每个开始都很小。', '📌 获得：小摄像机（1级）和旧麦克风（1级）。', '你终于来了！你父亲嘱咐我亲手把钥匙交给你。这里十年没人开过门，准备好迎接灰尘吧。', '走吧，萨利赫叔叔，看看还剩下什么。', '门开了：一张旧桌子、一间会议室，到处都是灰尘垃圾。', '这就是演播室？！', '这曾是街区里最好的演播室。现在轮到你让它重获新生了。', '📌 点击脏污处进行清理。', '先扫地，再收拾桌子。干净的地方让人精神振奋。', '📌 经验 +10。', '现在这里能喘口气了。但没有内容的演播室一文不值。去街上，和人们聊聊，拍下你的第一个采访。'],
  'zh-Hant': ['父親', '薩利赫叔叔', '你', '孩子，如果你收到這段錄音，我已經不在你身邊了。我留給你一樣珍貴的東西：On Air 攝影棚。那是我的第一個夢想，十年前我把它關了。', '鑰匙在薩利赫叔叔那裡。帶上盒子裡的小攝影機和麥克風。東西不多，但每個開始都很小。', '📌 獲得：小攝影機（1級）和舊麥克風（1級）。', '你終於來了！你父親囑咐我親手把鑰匙交給你。這裡十年沒人開過門，準備好迎接灰塵吧。', '走吧，薩利赫叔叔，看看還剩下什麼。', '門開了：一張舊桌子、一間會議室，到處都是灰塵垃圾。', '這就是攝影棚？！', '這曾是街區裡最好的攝影棚。現在輪到你讓它重獲新生了。', '📌 點擊髒污處進行清理。', '先掃地，再收拾桌子。乾淨的地方讓人精神振奮。', '📌 經驗 +10。', '現在這裡能喘口氣了。但沒有內容的攝影棚一文不值。去街上，和人們聊聊，拍下你的第一個採訪。'],
  sk: ['Otec', 'Strýko Saleh', 'Ty', 'Synu, ak sa k tebe dostane táto nahrávka, už nie som s tebou. Zanechávam ti niečo vzácne: štúdio On Air. Bol to môj prvý sen a pred desiatimi rokmi som ho zatvoril.', 'Kľúč má strýko Saleh. Vezmi si malú kameru a mikrofón z krabice. Nie je to veľa, ale každý začiatok je malý.', '📌 Získané: malá kamera (úroveň 1) a starý mikrofón (úroveň 1).', 'Konečne si prišiel! Tvoj otec ma požiadal, aby som ti kľúč dal osobne. Desať rokov tu nikto neotvoril, priprav sa na prach.', 'Poďme, strýko Saleh, pozrime sa, čo zostalo.', 'Dvere sa otvárajú: starý stôl, zasadačka a všade špina.', 'Toto je to štúdio?!', 'Bolo to najkrajšie štúdio v štvrti. Teraz je na tebe, aby si ho vrátil k životu.', '📌 Ťukni na špinu a uprac ju.', 'Začni podlahou, potom stôl. Čisté miesto zdvihne náladu.', '📌 +10 skúseností.', 'Teraz to tu dýcha. Ale štúdio bez obsahu nemá cenu. Choď von na ulicu, rozprávaj sa s ľuďmi a natoč svoj prvý rozhovor.'],
  sl: ['Oče', 'Stric Saleh', 'Ti', 'Sin, če te ta posnetek doseže, nisem več s tabo. Puščam ti nekaj dragocenega: studio On Air. Bil je moje prve sanje, pred desetimi leti pa sem ga zaprl.', 'Ključ ima stric Saleh. Vzemi malo kamero in mikrofon iz škatle. Ni veliko, a vsak začetek je majhen.', '📌 Prejeto: mala kamera (raven 1) in star mikrofon (raven 1).', 'Končno si prišel! Tvoj oče me je prosil, naj ti ključ izročim osebno. Deset let tega ni nihče odprl, pripravi se na prah.', 'Gremo, stric Saleh, poglejva, kaj je ostalo.', 'Vrata se odprejo: stara miza, sejna soba in umazanija povsod.', 'To je studio?!', 'Bil je najlepši studio v soseski. Zdaj je na tebi, da ga oživiš.', '📌 Tapni umazanijo, da jo očistiš.', 'Začni s tlemi, nato miza. Čist prostor dvigne razpoloženje.', '📌 +10 izkušenj.', 'Zdaj prostor diha. A studio brez vsebine ni vreden nič. Pojdi na ulico, govori z ljudmi in posnemi svoj prvi intervju.'],
  es: ['Papá', 'Tío Saleh', 'Tú', 'Hijo, si esta grabación te llega, ya no estoy contigo. Te dejo algo valioso: el estudio On Air. Fue mi primer sueño, y lo cerré hace diez años.', 'La llave la tiene el tío Saleh. Llévate la cámara pequeña y el micrófono de la caja. No es mucho, pero todo comienzo es pequeño.', '📌 Recibido: cámara pequeña (nivel 1) y micrófono viejo (nivel 1).', '¡Por fin viniste! Tu padre me pidió que te diera la llave en mano. Nadie ha abierto este lugar en diez años, prepárate para el polvo.', 'Vamos, tío Saleh, a ver qué queda.', 'La puerta se abre: un escritorio viejo, una sala de reuniones y suciedad por todas partes.', '¡¿Esto es el estudio?!', 'Era el mejor estudio del barrio. Ahora te toca a ti devolverle la vida.', '📌 Toca la suciedad para limpiarla.', 'Empieza por el suelo y luego el escritorio. Un lugar limpio levanta el ánimo.', '📌 +10 de experiencia.', 'Ahora el lugar respira. Pero un estudio sin contenido no vale nada. Sal a la calle, habla con la gente y graba tu primera entrevista.'],
  sw: ['Baba', 'Mjomba Saleh', 'Wewe', 'Mwanangu, kama rekodi hii itakufikia, mimi sipo nawe tena. Nakuachia kitu cha thamani: studio ya On Air. Ilikuwa ndoto yangu ya kwanza, na niliifunga miaka kumi iliyopita.', 'Ufunguo uko kwa Mjomba Saleh. Chukua kamera ndogo na kipaza sauti kilicho kwenye sanduku. Si vingi, lakini kila mwanzo ni mdogo.', '📌 Umepokea: kamera ndogo (kiwango 1) na kipaza sauti cha zamani (kiwango 1).', 'Hatimaye umekuja! Baba yako aliniagiza nikukabidhi ufunguo mwenyewe. Miaka kumi hakuna aliyefungua hapa, jiandae kwa vumbi.', 'Twende, Mjomba Saleh, tuone kilichobaki.', 'Mlango unafunguka: meza ya zamani, chumba cha mikutano na uchafu kila mahali.', 'Hii ndiyo studio?!', 'Ilikuwa studio bora mtaani. Sasa ni zamu yako kuirudisha.', '📌 Gusa uchafu ili kuusafisha.', 'Anza na sakafu, kisha meza. Mahali safi huinua moyo.', '📌 +10 uzoefu.', 'Sasa mahali panapumua. Lakini studio bila maudhui haina thamani. Nenda barabarani, ongea na watu, na urekodi mahojiano yako ya kwanza.'],
  sv: ['Pappa', 'Farbror Saleh', 'Du', 'Min son, om den här inspelningen når dig är jag inte längre hos dig. Jag lämnar dig något värdefullt: On Air-studion. Det var min första dröm, och jag stängde den för tio år sedan.', 'Farbror Saleh har nyckeln. Ta den lilla kameran och mikrofonen i lådan. Det är inte mycket, men varje början är liten.', '📌 Mottaget: liten kamera (nivå 1) och gammal mikrofon (nivå 1).', 'Äntligen kom du! Din pappa bad mig ge dig nyckeln personligen. Ingen har öppnat här på tio år, så gör dig redo för damm.', 'Kom igen, farbror Saleh, vi ser vad som finns kvar.', 'Dörren öppnas: ett gammalt skrivbord, ett mötesrum och smuts överallt.', 'Är det här studion?!', 'Det var kvarterets finaste studio. Nu är det din tur att väcka den till liv.', '📌 Tryck på smutsen för att städa bort den.', 'Börja med golvet, sedan skrivbordet. En ren plats höjer humöret.', '📌 +10 erfarenhet.', 'Nu kan platsen andas. Men en studio utan innehåll är inget värd. Gå ut på gatan, prata med folk och filma din första intervju.'],
  th: ['พ่อ', 'ลุงซอและห์', 'คุณ', 'ลูกเอ๋ย ถ้าเทปนี้ไปถึงลูก พ่อคงไม่ได้อยู่ข้างลูกแล้ว พ่อฝากสิ่งล้ำค่าไว้ให้ คือสตูดิโอ On Air มันเป็นความฝันแรกของพ่อ และพ่อปิดมันไปเมื่อสิบปีก่อน', 'กุญแจอยู่กับลุงซอและห์ เอากล้องตัวเล็กกับไมค์ในกล่องไปด้วย ไม่ได้มากมาย แต่ทุกการเริ่มต้นย่อมเริ่มจากเล็ก ๆ', '📌 ได้รับ: กล้องตัวเล็ก (เลเวล 1) และไมค์เก่า (เลเวล 1)', 'ในที่สุดก็มาจนได้! พ่อของเจ้าฝากให้ลุงมอบกุญแจให้กับมือ ที่นี่ไม่มีใครเปิดมาสิบปีแล้ว เตรียมใจเจอฝุ่นได้เลย', 'ไปกันเถอะลุงซอและห์ ไปดูว่าเหลืออะไรบ้าง', 'ประตูเปิดออก: โต๊ะเก่า ห้องประชุม และความสกปรกเต็มไปหมด', 'นี่น่ะหรือสตูดิโอ?!', 'เคยเป็นสตูดิโอที่สวยที่สุดในย่านนี้ ตอนนี้ถึงตาเจ้าทำให้มันกลับมาแล้ว', '📌 แตะที่ความสกปรกเพื่อทำความสะอาด', 'เริ่มจากพื้นก่อน แล้วค่อยโต๊ะ ที่ที่สะอาดทำให้ใจดีขึ้น', '📌 +10 ประสบการณ์', 'ตอนนี้ที่นี่หายใจได้แล้ว แต่สตูดิโอที่ไม่มีคอนเทนต์ก็ไม่มีค่าอะไร ออกไปที่ถนน คุยกับผู้คน แล้วถ่ายสัมภาษณ์ครั้งแรกของเจ้า'],
  tr: ['Baba', 'Salih Amca', 'Sen', 'Oğlum, bu kayıt sana ulaştıysa artık yanında değilim. Sana değerli bir emanet bırakıyorum: On Air stüdyosu. İlk hayalimdi ve on yıl önce kapattım.', 'Anahtar Salih Amca’da. Kutudaki küçük kamerayı ve mikrofonu al. Çok bir şey değil ama her başlangıç küçüktür.', '📌 Alındı: küçük kamera (seviye 1) ve eski mikrofon (seviye 1).', 'Sonunda geldin! Baban anahtarı bizzat sana vermemi istedi. On yıldır kimse burayı açmadı, toza hazır ol.', 'Hadi Salih Amca, neler kalmış görelim.', 'Kapı açılıyor: eski bir masa, bir toplantı odası ve her yerde kir.', 'Stüdyo bu mu?!', 'Mahallenin en güzel stüdyosuydu. Şimdi onu geri getirmek sana kaldı.', '📌 Temizlemek için kire dokun.', 'Önce zemin, sonra masa. Temiz bir yer insanın moralini yükseltir.', '📌 +10 deneyim.', 'Artık burası nefes alıyor. Ama içeriksiz bir stüdyo hiçbir şeye değmez. Sokağa çık, insanlarla konuş ve ilk röportajını çek.'],
  uk: ['Тато', 'Дядько Салех', 'Ти', 'Сину, якщо цей запис дійшов до тебе, мене вже немає поруч. Залишаю тобі щось цінне: студію On Air. Це була моя перша мрія, і десять років тому я її зачинив.', 'Ключ у дядька Салеха. Візьми маленьку камеру й мікрофон із коробки. Це небагато, але кожен початок малий.', '📌 Отримано: маленька камера (рівень 1) і старий мікрофон (рівень 1).', 'Нарешті ти прийшов! Твій батько просив віддати тобі ключ особисто. Десять років сюди ніхто не заходив, готуйся до пилу.', 'Ходімо, дядьку Салеху, подивимось, що лишилося.', 'Двері відчиняються: старий стіл, переговорна й бруд усюди.', 'Це і є студія?!', 'Це була найкраща студія в районі. Тепер твоя черга її відродити.', '📌 Торкайся бруду, щоб прибрати його.', 'Почни з підлоги, потім стіл. Чисте місце піднімає настрій.', '📌 +10 досвіду.', 'Тепер тут можна дихати. Але студія без контенту нічого не варта. Вийди на вулицю, поговори з людьми й зніми своє перше інтерв’ю.'],
  ur: ['ابو', 'صالح چچا', 'آپ', 'بیٹا، اگر یہ ریکارڈنگ تم تک پہنچی ہے تو میں اب تمہارے ساتھ نہیں ہوں۔ تمہارے لیے ایک قیمتی امانت چھوڑ رہا ہوں: On Air اسٹوڈیو۔ یہ میرا پہلا خواب تھا، اور دس سال پہلے میں نے اسے بند کر دیا۔', 'چابی صالح چچا کے پاس ہے۔ ڈبے سے چھوٹا کیمرہ اور مائیک لے لینا۔ زیادہ کچھ نہیں، مگر ہر آغاز چھوٹا ہی ہوتا ہے۔', '📌 ملا: چھوٹا کیمرہ (لیول 1) اور پرانا مائیک (لیول 1)۔', 'آخرکار تم آ گئے! تمہارے ابو نے کہا تھا کہ چابی میں خود تمہارے ہاتھ میں دوں۔ دس سال سے کسی نے یہ جگہ نہیں کھولی، گرد کے لیے تیار رہو۔', 'چلیں صالح چچا، دیکھیں کیا بچا ہے۔', 'دروازہ کھلتا ہے: ایک پرانی میز، ایک میٹنگ روم، اور ہر طرف گندگی۔', 'یہ ہے اسٹوڈیو؟!', 'یہ محلے کا سب سے خوبصورت اسٹوڈیو تھا۔ اب اسے واپس لانا تمہاری باری ہے۔', '📌 صاف کرنے کے لیے گندگی پر ٹیپ کریں۔', 'پہلے فرش، پھر میز۔ صاف جگہ دل کو خوش کرتی ہے۔', '📌 +10 تجربہ۔', 'اب یہ جگہ سانس لے رہی ہے۔ لیکن مواد کے بغیر اسٹوڈیو کی کوئی قیمت نہیں۔ سڑک پر جاؤ، لوگوں سے بات کرو، اور اپنا پہلا انٹرویو ریکارڈ کرو۔'],
  vi: ['Bố', 'Chú Saleh', 'Bạn', 'Con trai, nếu đoạn ghi âm này đến được với con, bố không còn bên con nữa. Bố để lại cho con một thứ quý giá: studio On Air. Đó là giấc mơ đầu tiên của bố, và bố đã đóng cửa nó mười năm trước.', 'Chìa khóa ở chỗ chú Saleh. Hãy mang theo chiếc máy quay nhỏ và micro trong hộp. Không nhiều, nhưng mọi khởi đầu đều nhỏ bé.', '📌 Nhận được: máy quay nhỏ (cấp 1) và micro cũ (cấp 1).', 'Cuối cùng cháu cũng đến! Bố cháu dặn chú phải tận tay trao chìa khóa. Mười năm rồi chẳng ai mở cửa, chuẩn bị tinh thần gặp bụi nhé.', 'Đi thôi chú Saleh, xem còn lại những gì.', 'Cánh cửa mở ra: một chiếc bàn cũ, một phòng họp và bụi bẩn khắp nơi.', 'Đây là studio sao?!', 'Từng là studio đẹp nhất khu này. Giờ đến lượt cháu hồi sinh nó.', '📌 Chạm vào vết bẩn để dọn sạch.', 'Bắt đầu từ sàn nhà, rồi đến bàn. Nơi sạch sẽ khiến tinh thần phấn chấn.', '📌 +10 kinh nghiệm.', 'Giờ nơi này đã dễ thở rồi. Nhưng studio không có nội dung thì chẳng đáng gì. Hãy ra phố, trò chuyện với mọi người và quay buổi phỏng vấn đầu tiên.'],
};
